import React, { useEffect, useState } from 'react';
import { AccessibilityInfo, AppState, AppStateStatus, StyleSheet, View } from 'react-native';
import { Image } from 'expo-image';
import { useNavigation } from '@react-navigation/native';

const GREETING = require('../../assets/mascot/kuya-sugo-greeting.webp');
const POSTER = require('../../assets/mascot/kuya-sugo-welcome.png');

/** One Blender-rendered greeting; no 3D engine runs on the customer's phone. */
export default function KuyaSugoMascot({ height = 176 }: { height?: number }) {
  const navigation = useNavigation();
  const [reducedMotion, setReducedMotion] = useState(true);
  const [appState, setAppState] = useState<AppStateStatus>(AppState.currentState ?? 'active');
  const [focused, setFocused] = useState(() => navigation.isFocused?.() ?? true);
  const [imageFailed, setImageFailed] = useState(false);

  useEffect(() => {
    let mounted = true;
    AccessibilityInfo.isReduceMotionEnabled().then(value => {
      if (mounted) setReducedMotion(value);
    }).catch(() => {});
    const motion = AccessibilityInfo.addEventListener('reduceMotionChanged', setReducedMotion);
    const app = AppState.addEventListener('change', setAppState);
    const focus = navigation.addListener('focus', () => setFocused(true));
    const blur = navigation.addListener('blur', () => setFocused(false));
    return () => { mounted = false; motion.remove(); app.remove(); focus(); blur(); };
  }, [navigation]);

  const playing = focused && appState === 'active' && !reducedMotion && !imageFailed;
  return <View style={[styles.frame, { height, width: height * 6 / 7 }]}>
    <Image testID="kuya-sugo-mascot" style={styles.image} source={playing ? GREETING : POSTER}
      autoplay={playing} contentFit="contain" transition={0} accessible
      accessibilityLabel="Kuya Sugo, your Sugo Express helper"
      onError={() => setImageFailed(true)} />
  </View>;
}

const styles = StyleSheet.create({
  frame: { alignSelf: 'center', marginBottom: 16 },
  image: { width: '100%', height: '100%' },
});
